contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address token, address to1, address to2, uint v1, uint v2) public {
        require(to1 != address(0) && to2 != address(0));
        address[] memory tos = new address[](2);
        tos[0] = to1;
        tos[1] = to2;
        uint[] memory vs = new uint[](2);
        vs[0] = v1;
        vs[1] = v2;
        bool ok = true;
        bool reverted = false;
        // single top-level state-changing call on c, guarded by try for revert rule
        try c.transfer(from, token, tos, vs) returns (bool r) { ok = r; } catch { reverted = true; }
        assert(!reverted && ok);
    }
    receive() external payable {}
}

